function focusGlobePlace(name){const place=D.universities.find(u=>u.name===name),canvas=$('#university-globe');if(!place||!canvas)return;const position=globeCoordinates[name];if(!position)return;const selected=state.favorites.map(find).filter(Boolean).some(p=>AtlasCore.belongsTo(p,name));const status=$('#globe-status');if(status)status.textContent=`${place.name} · ${place.city}${selected?' · nella tua selezione':''}`;for(const b of $$('[data-globe-focus]'))b.setAttribute('aria-pressed',String(b.dataset.globeFocus===name));globeState?.center?.(position[1],position[0]);const stage=canvas.closest('.globe-stage');stage?.classList.add('is-focused');setTimeout(()=>stage?.classList.remove('is-focused'),850)}
function overview(){
  const tracked=D.programs.filter(p=>rec(p.id).stage);
  const europe=D.programs.filter(p=>p.region==='Europa').length;
  const extra=D.programs.filter(p=>p.region==='Extra-Europa').length;
  const europeShare=Math.round(europe/Math.max(1,europe+extra)*100);
  const shown=(Number(homeTab)<3?D.universities:D.programs).filter(p=>p.region===(['1','3'].includes(homeTab)?'Europa':'Extra-Europa')).slice(0,5);
  const statusRows=stages.map(stage=>{const count=tracked.filter(p=>rec(p.id).stage===stage).length;return `<div class="stage-row"><span>${esc(stage)}</span><div class="stage-track"><i style="--stage-fill:${tracked.length?Math.max(6,Math.round(count/tracked.length*100)):0}%"></i></div><strong>${count}</strong></div>`}).join('');
  const applicationRows=tracked.slice().sort((a,b)=>(rec(a.id).deadline||'9999').localeCompare(rec(b.id).deadline||'9999')).slice(0,3);
  const shortlist=state.favorites.map(find).filter(Boolean).slice(0,3);
  const rankingRows=shown.map(p=>`<div class="top-row"><span class="rank">${String(p.rank).padStart(2,'0')}</span><div class="row-body"><h3>${p.university?`<button class="detail-link" data-detail="${p.id}" style="text-align:left;padding:0;color:inherit;font-weight:600">${esc(p.name)}</button>`:esc(p.name)}</h3><p>${esc(p.university||p.offer)} · ${esc(p.city)}</p></div>${p.university?heart(p):`<button class="icon-button" data-university="${esc(p.name)}" data-region="${p.region}" aria-label="Esplora ${esc(p.name)}">↗</button>`}</div>`).join('');
  $('#main').innerHTML=title('IL TUO SPAZIO','Il tuo atlante.','Percorsi, università e candidature raccolti in un unico spazio.',`<a class="button" href="#programs">Esplora i percorsi ↗</a>`)+`<section class="dashboard-grid" aria-label="Riepilogo del tuo atlante">
    ${globeCard()}
    <div class="dashboard-main">
      <article class="dashboard-card distribution-card">
        <div class="dashboard-card-head"><div><span class="eyebrow">IL DOSSIER</span><h2>Una panoramica.</h2></div><span class="glass-chip">MASTER · 2027</span></div>
        <div class="distribution-content"><div class="distribution-donut" style="--europe-share:${europeShare}%" role="img" aria-label="${europe} percorsi Europa e ${extra} extra-Europa"><div><strong>${europe+extra}</strong><small>percorsi</small></div></div><div class="distribution-legend"><button type="button" class="distribution-key" data-region-tab="Europa"><i class="key-dot europe-dot"></i><span>Europa</span><strong>${europe}</strong><small>${europeShare}%</small></button><button type="button" class="distribution-key" data-region-tab="Extra-Europa"><i class="key-dot extra-dot"></i><span>Extra-Europa</span><strong>${extra}</strong><small>${100-europeShare}%</small></button></div></div>
        <div class="dashboard-metrics"><a href="#universities"><span>Università</span><strong>${D.universities.length}</strong><small>nel dossier</small></a><a href="#favorites"><span>Shortlist</span><strong>${state.favorites.length.toString().padStart(2,'0')}</strong><small>percorsi salvati</small></a><a href="#applications"><span>Candidature</span><strong>${String(tracked.length).padStart(2,'0')}</strong><small>che stai seguendo</small></a></div>
      </article>
      <article class="dashboard-card ranking-card"><div class="dashboard-card-head"><div><span class="eyebrow">SCELTI PER TE</span><h2>Le classifiche.</h2></div><a class="subtle-link" href="#programs">Tutti i percorsi <span aria-hidden="true">↗</span></a></div><div class="ranking-tabs">${[['3','Percorsi Europa'],['4','Percorsi extra-Europa'],['1','Atenei Europa'],['2','Atenei extra-Europa']].map(([id,label])=>`<button class="tab ${homeTab===id?'active':''}" data-home-tab="${id}">${label}</button>`).join('')}</div><div class="dashboard-ranking-list">${rankingRows}</div><p class="dashboard-footnote">Classifiche qualitative del dossier: non sono ranking ufficiali né probabilità di ammissione.</p></article>
    </div>
    <aside class="dashboard-rail">
      <article class="dashboard-card focus-card"><span class="eyebrow">LA TUA BUSSOLA</span><div class="focus-orbit" aria-hidden="true"><span>✳</span></div><h2>Dalla cellula,<br>alle possibilità.</h2><p>Biologia cellulare, staminali e rigenerazione: il tuo interesse guida la ricerca.</p><div class="focus-tags"><span>Cellule</span><span>Sviluppo</span><span>Ricerca</span></div><a href="#programs" class="focus-link">Segui la tua curiosità <span aria-hidden="true">↗</span></a></article>
      <article class="dashboard-card activity-card"><div class="dashboard-card-head"><div><span class="eyebrow">IL PROSSIMO PASSO</span><h2>Candidature.</h2></div><a class="round-link" href="#applications" aria-label="Apri candidature">↗</a></div><div class="stage-list">${statusRows}</div>${applicationRows.length?`<div class="application-preview">${applicationRows.map(p=>`<button class="application-preview-row" data-detail="${p.id}"><span><strong>${esc(p.university)}</strong><small>${esc(p.name)}</small></span><em>${rec(p.id).deadline?esc(rec(p.id).deadline):esc(rec(p.id).stage)}</em></button>`).join('')}</div>`:'<p class="dashboard-empty">Quando scegli un percorso, qui troverai stati e scadenze.</p>'}<a class="focus-link" href="#applications">${tracked.length?'Apri il tuo piano':'Organizza il tuo piano'} <span aria-hidden="true">↗</span></a></article>
      <article class="dashboard-card shortlist-card"><div class="dashboard-card-head"><div><span class="eyebrow">DA TENERE VICINO</span><h2>La selezione.</h2></div><a class="round-link" href="#favorites" aria-label="Apri shortlist">↗</a></div>${shortlist.length?shortlist.map(p=>`<button class="shortlist-row" data-detail="${p.id}"><span class="shortlist-rank">#${p.rank}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.university)} · ${esc(p.city)}</small></span><span aria-hidden="true">↗</span></button>`).join(''):'<p class="dashboard-empty">I percorsi che salvi con il cuore appariranno qui.</p><a href="#programs" class="focus-link">Trova il primo <span aria-hidden="true">↗</span></a>'}</article>
    </aside>
  </section>`;
  mountDashboardGlobe();
}
function card(p){return `<article class="program-card"><div class="card-top"><span class="rank-badge"><strong>#${p.rank}</strong> · ${p.region}</span>${heart(p)}</div><button class="card-title" data-detail="${p.id}">${esc(p.name)}</button><p class="card-university">${esc(p.university)}</p><p class="card-city">⌖ ${esc(p.city)}</p><div class="badges">${badge(p)}${rec(p.id).stage?`<span class="badge">${esc(rec(p.id).stage)}</span>`:''}</div><div class="card-bottom">${checkbox(p)}<button class="detail-link" data-detail="${p.id}">Apri scheda ↗</button></div></article>`}
function filtered(){const q=query.toLocaleLowerCase();let a=D.programs.filter(p=>(region==='Tutte'||p.region===region)&&(!uni||AtlasCore.belongsTo(p,uni))&&(!kind||p.type===kind)&&(!condition||(condition==='none'?p.conditions==='—':p.conditions.split(/[·, /]+/).includes(condition)))&&(!(view==='favorites'||favoritesOnly)||state.favorites.includes(p.id))&&(!q||[p.name,p.university,p.city,...p.notes].join(' ').toLocaleLowerCase().includes(q)));a.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='university'?a.university.localeCompare(b.university)||a.rank-b.rank:a.region.localeCompare(b.region)||a.rank-b.rank);return a}
function catalog(){const favorite=view==='favorites';$('#main').innerHTML=title(favorite?'LE POSSIBILITÀ CHE CONTANO':'TROVA LA TUA DIREZIONE',favorite?'La mia selezione.':'Un mondo di possibilità.',favorite?'I tuoi percorsi preferiti, con note e candidature sempre a portata di mano.':'Tutte le 208 voci del dossier, con posizioni, link e condizioni originali.',`<button class="button" data-export-csv>↓ Esporta risultati CSV</button>`)+`<div class="ranking-tabs">${['Europa','Extra-Europa','Tutte'].map(r=>`<button class="tab ${region===r?'active':''}" data-region-tab="${r}">${r}${r==='Tutte'?' · 208':r==='Europa'?' · 146':' · 62'}</button>`).join('')}</div><div class="toolbar"><div class="search"><input id="search" type="search" placeholder="Cerca un percorso, una città, un’università…" aria-label="Cerca percorsi" value="${esc(query)}"></div><select id="university-filter" aria-label="Filtra università"><option value="">Tutte le università</option>${[...new Set([...D.programs.map(p=>p.university),...D.programs.flatMap(p=>p.partners||[])])].sort().map(u=>`<option ${uni===u?'selected':''}>${esc(u)}</option>`).join('')}</select><select id="type-filter" aria-label="Filtra tipo"><option value="">Tutti i tipi</option>${[...new Set(D.programs.map(p=>p.type))].sort().map(t=>`<option ${kind===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="condition-filter" aria-label="Filtra condizioni"><option value="">Tutte le condizioni</option>${[['none','Nessuna sigla'],['DE','DE · Tedesco'],['L','L · Lingua da verificare'],['E','E · Piano in inglese'],['A','A · Accesso particolare'],['?','? · 2027 da confermare'],['CN','CN · In Cina']].map(([v,l])=>`<option value="${v}" ${condition===v?'selected':''}>${l}</option>`).join('')}</select><select id="sort" aria-label="Ordina risultati">${[['rank','Ordine del dossier'],['name','Nome A–Z'],['university','Università A–Z']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select><button class="button" data-reset-filters>Ripristina filtri</button></div><div class="result-bar"><span id="result-count"></span><div class="view-switch"><button class="chip ${layout==='cards'?'active':''}" data-layout="cards" aria-label="Vista schede">▦ Schede</button><button class="chip ${layout==='table'?'active':''}" data-layout="table" aria-label="Vista tabella">☷ Tabella</button></div></div><div id="results"></div>`;renderResults()}
function renderResults(){const a=filtered();$('#result-count').textContent=`${a.length} percorsi · ${region==='Tutte'?'Le posizioni sono separate per area geografica':region}`;$('#results').innerHTML=a.length?(layout==='cards'?`<div class="cards">${a.map(card).join('')}</div>`:`<div class="table-wrap"><table class="data-table"><thead><tr><th>POSIZIONE</th><th>PERCORSO</th><th>UNIVERSITÀ / CITTÀ</th><th>TIPO / CONDIZIONI</th><th>SELEZIONA</th></tr></thead><tbody>${a.map(p=>`<tr><td>#${p.rank}<br>${p.region}</td><td><button class="table-title" data-detail="${p.id}">${esc(p.name)}</button></td><td>${esc(p.university)}<br><small>${esc(p.city)}</small></td><td>${badge(p)}</td><td>${heart(p)} ${checkbox(p)}</td></tr>`).join('')}</tbody></table></div>`):`<div class="empty"><h2>${view==='favorites'?'La tua shortlist inizia da una curiosità.':'Nessun percorso trovato.'}</h2><p>${view==='favorites'?'Salva i percorsi con il cuore per ritrovarli qui.':'Prova a cambiare ricerca o a ripristinare i filtri.'}</p><a class="button" href="#programs">Esplora i percorsi ↗</a></div>`}
function universities(){$('#main').innerHTML=title('QUATTRO CLASSIFICHE · ATENEI','I luoghi delle tue idee.','27 università del dossier. Le collaborazioni dei singoli programmi restano nelle rispettive schede.')+`<div class="ranking-tabs">${['Europa','Extra-Europa','Tutte'].map(r=>`<button class="tab ${region===r?'active':''}" data-region-tab="${r}">${r}</button>`).join('')}</div><div class="university-grid">${D.universities.filter(u=>region==='Tutte'||u.region===region).map(u=>`<article class="uni-card"><div class="card-top"><div class="uni-monogram">${esc(u.name.slice(0,2))}</div><span class="rank-badge">#${u.rank} · ${u.region}</span></div><h2>${esc(u.name)}</h2><small class="card-city">⌖ ${esc(u.city)}</small><p>${esc(u.offer)}</p><button class="button" data-university="${esc(u.name)}" data-region="${u.region}">Esplora i percorsi ↗</button></article>`).join('')}</div>`}
function comparison(){const a=state.compare.map(find).filter(Boolean);$('#main').innerHTML=title('AFFIANCA LE TUE POSSIBILITÀ','Una scelta più chiara.','Confronta fino a quattro percorsi. Le posizioni appartengono alle rispettive classifiche.',`<button class="button" data-clear-compare>Svuota confronto</button>`)+(a.length?`<div class="compare-wrap"><table class="compare-table"><thead><tr><th>Percorsi</th>${a.map(p=>`<th>${esc(p.name)}<br><button class="detail-link" data-remove-compare="${p.id}">Rimuovi ×</button></th>`).join('')}</tr></thead><tbody>${[['Posizione',p=>`#${p.rank} · ${p.region}`],['Università',p=>esc(p.university)],['Sede',p=>esc(p.city)],['Tipo',p=>`${esc(p.type)}<br><small>${esc(typeExplanation(p.type))}</small>`],['Condizioni',p=>conditionsText(p)],['Note del dossier',p=>esc(p.notes.join(' ')||'Nessuna nota associata. Consulta anche il dossier integrale.')],['Candidatura',p=>esc(rec(p.id).stage||'Non monitorata')],['Scadenza personale',p=>esc(rec(p.id).deadline||'Non inserita')],['Le tue note',p=>esc(rec(p.id).notes||'—')],['Azioni',p=>`<button class="button" data-detail="${p.id}">Apri scheda ↗</button>`]].map(([label,fn])=>`<tr><td>${label}</td>${a.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">Le graduatorie misurano affinità e contesto di ricerca in modo qualitativo. Non stimano le probabilità di ingresso.</div>`:`<div class="empty"><h2>Metti le alternative una accanto all’altra.</h2><p>Seleziona “Confronta” sulle schede dei percorsi per iniziare.</p><a class="button primary" href="#programs">Scegli i percorsi ↗</a></div>`)}
function deadlineStatus(date){if(!date)return '';const today=new Date();const local=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;return date<local?'overdue':''}
function applications(){const a=D.programs.filter(p=>rec(p.id).stage);$('#main').innerHTML=title('DALLE IDEE AI PROSSIMI PASSI','Le tue candidature.','Organizza il percorso, aggiungi scadenze e tieni traccia dei documenti.',`<a class="button primary" href="#programs">+ Scegli un percorso</a>`)+`<div class="notice">Le scadenze si inseriscono nelle schede dopo la verifica sul sito ufficiale. Nessuna data è stata dedotta dal dossier. Spostare una scheda in “Inviata” registra il tuo stato: non invia una candidatura.</div><div class="board">${stages.map(s=>`<section class="column"><h2>${s}<b>${a.filter(p=>rec(p.id).stage===s).length}</b></h2>${a.filter(p=>rec(p.id).stage===s).sort((a,b)=>(rec(a.id).deadline||'9999').localeCompare(rec(b.id).deadline||'9999')).map(p=>`<article class="application"><span class="eyebrow" style="font-size:8px">${esc(p.university)}</span><h3><button class="table-title" data-detail="${p.id}">${esc(p.name)}</button></h3><p>${esc(p.city)}</p>${rec(p.id).deadline?`<span class="deadline ${deadlineStatus(rec(p.id).deadline)}">◷ ${esc(rec(p.id).deadline)} ${deadlineStatus(rec(p.id).deadline)?'· trascorsa':''}</span>`:'<span class="deadline">Nessuna scadenza inserita</span>'}<select data-stage="${p.id}" aria-label="Stato candidatura ${esc(p.name)}">${stages.map(t=>`<option ${s===t?'selected':''}>${t}</option>`).join('')}</select></article>`).join('')}${!a.some(p=>rec(p.id).stage===s)?'<p class="subtitle" style="font-size:11px">I tuoi prossimi passi appariranno qui.</p>':''}</section>`).join('')}</div>`}
function sourcePage(){$('#main').innerHTML=title('LE BASI DEL TUO ATLANTE','Il dossier, senza perdere nulla.','Contenuti originali aggiornati al 16 ottobre 2026, con legenda e voci storiche.',`<button class="button" data-download-source>↓ Scarica dossier .md</button>`)+`<div class="method"><p>Le quattro graduatorie del documento combinano affinità scientifica, ricerca sperimentale e ambiente dell’ateneo. Sono valutazioni qualitative personali, non ranking ufficiali o misure di ammissibilità. I dati non sono stati aggiornati con una verifica online.</p><p><b>208 voci classificate non significano 208 titoli autonomi:</b> contenitori di Master, track, M1/M2 e varianti sono conservati con il loro tipo. I 27 atenei principali possono partecipare ad accordi con altri partner. Le classifiche seguono l’ateneo di riferimento del dossier: la sede fisica può essere in un altro continente.</p></div><div class="section-heading"><h2>Una legenda per orientarti</h2></div><div class="legend">${Object.entries(legend).map(([k,v])=>`<div><b>${esc(k)}</b>${esc(v)}</div>`).join('')}</div><div class="notice">Un campo condizioni vuoto non certifica l’idoneità. Transcript, CFU, inglese e bandi vanno controllati per tutti. Per UNIL, la verifica del dossier usa il catalogo svizzero, non la pagina diretta dell’ateneo.</div><div class="section-heading"><h2>Note sui programmi · ${D.notes.length}</h2></div><details class="panel"><summary style="padding:20px;cursor:pointer">Apri tutte le note originali</summary>${D.notes.map(n=>`<div class="archive-item"><b>${esc(n.key)}</b><p>${esc(n.text)}</p></div>`).join('')}</details><div class="section-heading"><h2>Offerte storiche e sole mobilità · ${D.archived.length}</h2></div><details class="panel"><summary style="padding:20px;cursor:pointer">Consulta voci rinominate, non attive o da riconfermare</summary>${D.archived.map(p=>`<div class="archive-item"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(p.name)} ↗</b></a><p>${esc(p.university)} · ${esc(p.city)}</p><p>${esc(p.status)}</p></div>`).join('')}</details><div class="section-heading"><h2>Documento integrale</h2></div><details class="panel"><summary style="padding:20px;cursor:pointer">Leggi il file originale completo</summary><div class="source-text">${esc(D.source)}</div></details><div class="section-heading"><h2>I tuoi dati personali</h2></div><p class="method">${CLOUD_SYNC?'Preferiti, note e candidature vengono sincronizzati nel tuo spazio privato dopo l’accesso con ChatGPT. Una copia locale permette di lavorare offline. Sono disponibili copie di recupero automatiche locali e cloud.':'Questa versione è pubblica e non richiede un account. Preferiti, note, checklist e candidature sono personali e vengono salvati solo su questo browser: non sono visibili agli altri visitatori e non si sincronizzano tra dispositivi. Esporta un backup JSON per conservarli o trasferirli. Sono disponibili fino a dieci copie locali di recupero.'} Il CSV contiene i risultati della selezione corrente.</p><button class="button" data-backup>↓ Esporta backup JSON</button> <button class="button" data-import>↑ Importa backup JSON</button> <button class="button" data-recovery>↺ Copie di recupero</button>`}
function typeExplanation(type){if(type.startsWith('M1–M2'))return 'Percorso francese M1–M2; ·M indica mobilità.';return type.split('·').map(t=>legend[t]||t).join(' ')}
function conditionsText(p){if(p.conditions==='—')return 'Nessuna sigla nel dossier. Idoneità, CFU, lingua e bando da verificare.';return p.conditions.split(/[·, /]+/).filter(Boolean).map(s=>`${esc(s)}: ${esc(legend[s]||'Consulta il dossier.')}`).join('<br>')}
function openDetail(id){const p=find(id);if(!p)return;const r=rec(id);$('#detail-content').innerHTML=`<div class="dialog-head"><button class="icon-button dialog-close" data-close aria-label="Chiudi scheda">×</button><div class="eyebrow">#${p.rank} · ${p.region} · DOSSIER 2027</div><h2>${esc(p.name)}</h2><div class="card-university">${esc(p.university)} · ${esc(p.city)}</div><div class="badges">${badge(p)}</div></div><div class="dialog-body"><div class="dialog-meta"><div><small>TIPO DI PERCORSO</small>${esc(typeExplanation(p.type))}</div><div><small>CONDIZIONI NEL DOSSIER</small>${conditionsText(p)}</div></div>${p.notes.length?`<div class="eyebrow">NOTE DEL DOSSIER</div>${p.notes.map(n=>`<p>${esc(n)}</p>`).join('')}`:'<p>Consulta il dossier integrale per ulteriori precisazioni sul percorso.</p>'}<a class="button" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Sito ufficiale ↗</a><form id="record-form" data-id="${id}"><div class="section-heading"><h2>Il tuo piano</h2>${heart(p)}</div><div class="two-fields"><label class="field">Stato della candidatura<select name="stage"><option value="">Non monitorata</option>${stages.map(s=>`<option ${r.stage===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Scadenza verificata da te<input type="date" name="deadline" value="${esc(r.deadline||'')}" min="2020-01-01" max="2040-12-31"></label></div><label class="field">Link al bando / fonte della scadenza<input type="url" name="deadlineUrl" placeholder="https://…" value="${esc(r.deadlineUrl||'')}"></label><label class="field">Le tue note<textarea name="notes" placeholder="Laboratori interessanti, requisiti da controllare, idee per il progetto…">${esc(r.notes||'')}</textarea></label><div class="eyebrow">LA TUA CHECKLIST</div><div class="checklist">${['CV','Motivazione','Transcript','Inglese','Referenze'].map((s,i)=>`<label><input type="checkbox" name="check${i}" ${r.checklist?.includes(i)?'checked':''}>${s}</label>`).join('')}</div><div class="dialog-actions"><label class="compare-check"><input type="checkbox" data-compare="${id}" ${state.compare.includes(id)?'checked':''}> Confronta questo percorso</label><button type="submit" class="button primary">Salva il mio piano ✓</button></div><p style="font-size:10px">${CLOUD_SYNC?'Salvataggio automatico · copia locale e sincronizzazione privata.':'Salvataggio automatico solo su questo browser. Esporta un backup per conservare o trasferire i progressi.'} Nessuna candidatura viene inviata.</p></form></div>`;$$('button[data-fav]',$('#record-form')).forEach(b=>b.type='button');$('#detail').showModal()}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function backup(){download('master-atlas-backup.json',JSON.stringify({app:'master-atlas-2027',version:2,exported:new Date().toISOString(),state},null,2),'application/json');toast('Backup esportato')}
function csv(){const lines=[['Area','Posizione','Programma','Università','Città','Tipo','Condizioni','URL','Preferito','Stato candidatura','Scadenza personale','Note personali'],...filtered().map(p=>[p.region,p.rank,p.name,p.university,p.city,p.type,p.conditions,p.url,state.favorites.includes(p.id)?'Sì':'No',rec(p.id).stage||'',rec(p.id).deadline||'',rec(p.id).notes||''])];const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download('master-atlas-selezione.csv','\uFEFF'+lines.map(row=>row.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-university]');if(!b)return;
 if(b.id==='profile-toggle'){const actions=$('#profile-actions'),open=actions?.hidden;if(actions){actions.hidden=!open;b.setAttribute('aria-expanded',String(open));}return}
 if(b.closest('#profile-actions')){closeProfileMenu();}
 if(b.id==='theme-toggle'){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);return}
 if(b.id==='command-toggle'){openCommandPalette();return}
 if(b.dataset.commandView){$('#command-palette').close();location.hash=b.dataset.commandView;return}
 if(b.dataset.commandProgram){$('#command-palette').close();openDetail(b.dataset.commandProgram);return}
 if(b.dataset.detail){openDetail(b.dataset.detail);return}
 if(b.dataset.globeFocus){focusGlobePlace(b.dataset.globeFocus);return}
 if(b.hasAttribute('data-globe-north')){globeState?.north?.();return}
 if(b.dataset.globeZoom){if(b.dataset.globeZoom==='reset')globeState?.reset?.();else globeState?.zoom?.(b.dataset.globeZoom==='in'?.15:-.15);return}
 if(b.hasAttribute('data-close')){flushDraft();$('#detail').close();return}
 if(b.dataset.fav){const id=b.dataset.fav;state.favoritesUpdated[id]={selected:!state.favorites.includes(id),updatedAt:Date.now()};state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();b.classList.toggle('selected',state.favorites.includes(id));b.textContent=state.favorites.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',state.favorites.includes(id));b.setAttribute('aria-label',`${state.favorites.includes(id)?'Rimuovi dai':'Aggiungi ai'} preferiti: ${find(id).name}`);if(!$('#detail').open)render();else updateChrome();return}
 if(b.dataset.homeTab){homeTab=b.dataset.homeTab;render();return}
 if(b.dataset.regionTab){region=b.dataset.regionTab;uni='';render();return}
 if(b.dataset.layout){layout=b.dataset.layout;catalog();return}
 if(b.dataset.university){const mappings={'Queensland — UQ':'UQ','Erasmus University / Erasmus MC':'Erasmus MC'};const name=mappings[b.dataset.university]||b.dataset.university;region=b.dataset.region;uni=name;kind='';condition='';query='';if(!D.programs.some(p=>AtlasCore.belongsTo(p,uni))){uni='';query=name}if(view==='programs')catalog();else location.hash='programs';return}
 if(b.hasAttribute('data-reset-filters')){query='';uni='';kind='';condition='';sort='rank';catalog();return}
 if(b.hasAttribute('data-clear-compare')){state.compare=[];state.compareUpdated=Date.now();save();render();return}
 if(b.dataset.removeCompare){state.compare=state.compare.filter(id=>id!==b.dataset.removeCompare);state.compareUpdated=Date.now();save();render();return}
 if(b.hasAttribute('data-export-csv')){csv();return}
 if(b.id==='backup'||b.hasAttribute('data-backup')){backup();return}
 if(b.hasAttribute('data-recovery')){showRecovery();return}
 if(b.id==='import-button'||b.hasAttribute('data-import')){$('#import-file').click();return}
 if(b.hasAttribute('data-download-source'))download('Quattro_classifiche_complete_Master_2027.md',D.source,'text/markdown;charset=utf-8');
});
document.addEventListener('input',e=>{if(e.target.id==='command-search'){renderCommandResults()}else if(e.target.id==='search'){query=e.target.value;renderResults()}else if(e.target.closest('#record-form'))scheduleDraft()});
function closeProfileMenu(){const actions=$('#profile-actions'),toggle=$('#profile-toggle');if(actions&&!actions.hidden){actions.hidden=true;toggle?.setAttribute('aria-expanded','false')}}
document.addEventListener('click',e=>{if(!e.target.closest('#profile-menu'))closeProfileMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfileMenu();const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette();return}if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!typing){e.preventDefault();openCommandPalette();return}const dialog=$('#command-palette');if(!dialog?.open)return;if(e.key==='Enter'&&document.activeElement===$('#command-search')){e.preventDefault();$('.command-option',dialog)?.click();return}if(!['ArrowDown','ArrowUp'].includes(e.key))return;const options=$$('.command-option',dialog);if(!options.length)return;e.preventDefault();const current=options.indexOf(document.activeElement),delta=e.key==='ArrowDown'?1:-1;options[current<0?(delta>0?0:options.length-1):(current+delta+options.length)%options.length].focus()});
document.addEventListener('change',e=>{const t=e.target;if(t.closest('#record-form')&&!t.dataset.compare)scheduleDraft();if(t.dataset.compare){const id=t.dataset.compare;if(t.checked&&state.compare.length>=4){t.checked=false;toast('Puoi confrontare fino a quattro percorsi. Rimuovine uno per continuare.');return}state.compare=t.checked?[...new Set([...state.compare,id])]:state.compare.filter(x=>x!==id);state.compareUpdated=Date.now();save();updateChrome();return}
 if(t.dataset.stage){state.records[t.dataset.stage]={...rec(t.dataset.stage),stage:t.value,updatedAt:Date.now()};save();applications();return}
 if(['university-filter','type-filter','condition-filter','sort'].includes(t.id)){if(t.id==='university-filter')uni=t.value;if(t.id==='type-filter')kind=t.value;if(t.id==='condition-filter')condition=t.value;if(t.id==='sort')sort=t.value;renderResults()}
});
document.addEventListener('submit',e=>{if(e.target.id!=='record-form')return;e.preventDefault();draftDirty=false;clearTimeout(draftTimer);const f=e.target;const values=new FormData(f);state.records[f.dataset.id]={stage:values.get('stage'),deadline:values.get('deadline'),deadlineUrl:values.get('deadlineUrl'),notes:values.get('notes'),updatedAt:Date.now(),checklist:[0,1,2,3,4].filter(i=>values.has('check'+i))};const ok=save();$('#detail').close();render();if(ok)toast('Il tuo piano è stato salvato ✓')});
$('#import-file').addEventListener('change',async e=>{
  try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error();previewImport(JSON.parse(await f.text()));}
  catch{toast('Backup non valido. Seleziona un JSON esportato da Master Atlas.');}
  finally{e.target.value='';}
});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#detail').addEventListener('close',()=>{flushDraft();if(D)render()});
$('#detail').addEventListener('cancel',flushDraft);
$('#command-palette').addEventListener('click',e=>{if(e.target===$('#command-palette')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('pagehide',flushDraft);
document.addEventListener('visibilitychange',()=>{if(document.hidden)flushDraft()});
function route(){
  const target=location.hash.slice(1)||'overview';
  flushDraft();
  if($('#detail').open)$('#detail').close();
  if(target!==view){query='';uni='';kind='';condition='';sort='rank';region='Tutte';}
  view=Object.hasOwn(labels,target)?target:'overview';const paint=()=>render();const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(document.startViewTransition&&!reduced)document.startViewTransition(paint);else paint();window.scrollTo(0,0);
}
window.addEventListener('hashchange',route);
const appReady=globalThis.ATLAS_CONFIG?.accounts===true?globalThis.AtlasAuth.ready:Promise.resolve(null);
appReady.then(user=>{
  if(globalThis.ATLAS_CONFIG?.accounts===true&&!user)return;
  return fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(async d=>{
    D=d;
    store=new AtlasStore(D,next=>{const changed=JSON.stringify(state)!==JSON.stringify(next);state=next;if(changed&&!$('#detail').open)render();else updateChrome();},updateSync);
    state=store.state;route();await store.start();
  });
}).catch(()=>{$('#main').innerHTML='<div class="empty"><h2>Non riesco a caricare il dossier.</h2><p>Ricarica la pagina per riprovare.</p><button class="button" onclick="location.reload()">Ricarica</button></div>'});
if(document.documentElement?.dataset)setTheme(document.documentElement.dataset.theme||'light');
